/* data/learn-c/mth-11-04.js - GENERATED by tools/build_learn.py from data/learn/summaries/mth-11-04.json (our own words;
 * the notes of one chapter, loaded when the chapter is opened). Do not edit by hand. */
(window.LEARN_C = window.LEARN_C || {})["mth-11-04"] = {"7.1":{"s":"A conic is the path of a point whose distance from a fixed point, the focus, keeps a constant ratio e to its distance from a fixed line, the directrix. The ratio e is the eccentricity. Cutting a cone with a plane gives these curves. If e = 1 the conic is a parabola, if e is between 0 and 1 it is an ellipse, and if e is more than 1 it is a hyperbola.","f":[{"x":"SP/PM = e","n":"P is a point on the conic, S the focus, PM the perpendicular distance from P to the directrix, e the eccentricity.","r":"Balbharati Maths XI Part 1, p.176"}],"w":["e = 1 parabola, e < 1 ellipse, e > 1 hyperbola. A rectangular hyperbola has e = √2."]},"7.2":{"s":"With the centre or vertex at the origin and the axes along the coordinate axes, each conic has a standard equation. The parabola y² = 4ax has focus (a, 0) and directrix x = −a. The ellipse x²/a² + y²/b² = 1 (a > b) has its longer axis along x. The hyperbola x²/a² − y²/b² = 1 has its transverse axis along x. The sum of the focal distances of an ellipse point is the major axis.","f":[{"x":"y^2 = 4*a*x","n":"Parabola with focus (a, 0) and directrix x = -a. With the y-axis as axis: x^2 = 4*b*y.","r":"Balbharati Maths XI Part 1, p.143"},{"x":"SP = x_1 + a","n":"Focal distance of the point (x_1, y_1) on the parabola y^2 = 4*a*x.","r":"Balbharati Maths XI Part 1, p.143"},{"x":"l = 4*a","n":"Length of the latus rectum of y^2 = 4*a*x; its end points are (a, 2a) and (a, -2a).","r":"Balbharati Maths XI Part 1, p.143"},{"x":"x^2/a^2 + y^2/b^2 = 1","n":"Ellipse with a > b. Major axis 2a, minor axis 2b, centre at the origin.","r":"Balbharati Maths XI Part 1, p.176"},{"x":"b^2 = a^2*(1 - e^2)","n":"Ellipse: foci (a*e, 0) and (-a*e, 0), directrices x = a/e and x = -a/e, latus rectum 2*b^2/a.","r":"Balbharati Maths XI Part 1, p.155"},{"x":"x^2/a^2 - y^2/b^2 = 1","n":"Hyperbola with transverse axis 2a along the x-axis.","r":"Balbharati Maths XI Part 1, p.176"},{"x":"b^2 = a^2*(e^2 - 1)","n":"Hyperbola: foci (a*e, 0) and (-a*e, 0), directrices x = a/e and x = -a/e. The distance between the directrices is 2a/e.","r":"Balbharati Maths XI Part 1, p.169"}],"w":["Ellipse: b² = a²(1 − e²). Hyperbola: b² = a²(e² − 1). The sign of the bracket is the usual slip.","Parabola: focal distance is x + a (abscissa plus a), not just the abscissa."]},"7.3":{"s":"A tangent touches a conic at one point. To find the tangent at a point (x1, y1) on the curve, use the standard tangent equation: replace x² by x·x1 and y² by y·y1, and the linear terms by their average form. The parabola needs the term 2a(x + x1). The tangent to the parabola in terms of its slope m is y = mx + a/m. The point where it touches the curve is the point of contact.","f":[{"x":"y*y_1 = 2*a*(x + x_1)","n":"Tangent to the parabola y^2 = 4*a*x at the point (x_1, y_1); derived by differentiating, p.147.","r":"Balbharati Maths XI Part 1, p.147"},{"x":"x*x_1/a^2 + y*y_1/b^2 = 1","n":"Tangent to the ellipse x^2/a^2 + y^2/b^2 = 1 at (x_1, y_1).","r":"Balbharati Maths XI Part 1, p.175"},{"x":"x*x_1/a^2 - y*y_1/b^2 = 1","n":"Tangent to the hyperbola x^2/a^2 - y^2/b^2 = 1 at (x_1, y_1).","r":"Balbharati Maths XI Part 1, p.175"},{"x":"x*x_1 + y*y_1 = a^2","n":"Tangent to the circle x^2 + y^2 = a^2 at (x_1, y_1).","r":"Balbharati Maths XI Part 1, p.175"}],"w":["The table on p.175 prints the parabola tangent with a slip (x1 − y1). The correct form, derived on p.147, is yy1 = 2a(x + x1).","The point (x1, y1) must lie on the curve; if it does not, this equation is not a tangent."]},"7.4":{"s":"The line y = mx + c touches a conic only when c has a special value. Substitute the line into the curve, or compare it with the tangent equation, and force a double root. The result is the condition for tangency. For the parabola it fixes c in terms of a and m. For the ellipse and hyperbola it gives c² in terms of a, b and m. The same working gives the point of contact.","f":[{"x":"c = a/m","n":"Condition for the line y = m*x + c to touch the parabola y^2 = 4*a*x. The point of contact is (a/m^2, 2*a/m).","r":"Balbharati Maths XI Part 1, p.147"},{"x":"c^2 = a^2*m^2 + b^2","n":"Condition for y = m*x + c to touch the ellipse x^2/a^2 + y^2/b^2 = 1.","r":"Balbharati Maths XI Part 1, p.175"},{"x":"c^2 = a^2*m^2 - b^2","n":"Condition for y = m*x + c to touch the hyperbola x^2/a^2 - y^2/b^2 = 1.","r":"Balbharati Maths XI Part 1, p.175"},{"x":"c^2 = a^2*m^2 + a^2","n":"Condition for y = m*x + c to touch the circle x^2 + y^2 = a^2.","r":"Balbharati Maths XI Part 1, p.175"}],"w":["Ellipse has plus b², hyperbola has minus b². The parabola condition is c = a/m, not c².","Slope m of the tangent is given or found first; the two values of c from c² give the two parallel tangents."]}};
